@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet.</div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">@recipe.Title</h4>
                            <p class="text-muted">
                                ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@recipe.Title</h1>
        <p class="text-muted">Category: @recipe.Category | ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</p>

        <div class="card mb-4">
            <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
            <div class="card-body">
                <ul class="mb-0">
                    @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
            <div class="card-body">
                @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <p class="mb-1">@step</p>
                }
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-header"><h5 class="mb-0">⭐ Rate This Recipe</h5></div>
            <div class="card-body">
                <StarRating RecipeId="@recipe.Id" @rendermode="InteractiveServer" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span
            class="star @(star <= selectedRating ? "selected" : "")"
            @onclick="() => Rate(star)"
            style="cursor: pointer; font-size: 2rem; color: @(star <= selectedRating ? "gold" : "#ccc");">
            ★
        </span>
    }

    @if (submitted)
    {
        <p class="text-success mt-2">Thanks for rating! You gave @selectedRating star(s).</p>
    }
    else
    {
        <p class="text-muted mt-2">Click a star to rate this recipe.</p>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/submit"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@rendermode InteractiveServer

@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit Your Recipe</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe Submitted!</h4>
            <p>Your recipe "<strong>@title</strong>" has been added to the community.</p>
            <a href="/category/@category" class="btn btn-primary">View in @category</a>
        </div>
    }
    else
    {
        <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label class="form-label" for="title">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => title" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="category">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label class="form-label" for="ingredients">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="ingredients"
                    placeholder="One ingredient per line or comma-separated" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="steps">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="steps"
                    placeholder="Describe each step on a new line" />
            </div>

            <button type="submit" class="btn btn-success" disabled="@(string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category))">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category))
            return;

        var recipe = new Recipe
        {
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };

        RecipeService.AddRecipe(recipe);
        submitted = true;
    }
}

